"use client";
import { useState, useEffect } from "react";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/separator";
import { getProfile, updateProfile, uploadAvatar } from "@/app/api/doctor/profile";

const initialProfile = {
  avatarUrl: null,
  fullName: "",
  email: "",
  phone: "",
  gender: "",
  age: "",
  address: { country: "" },
  qualifications: [],
  availability: { days: [], timeSlots: "" },
  specialization: "",
  experience: "",
};

export default function DoctorProfilePage() {
  const [profile, setProfile] = useState(initialProfile);
  const [avatarUrl, setAvatarUrl] = useState(profile.avatarUrl);
  const [uploading, setUploading] = useState(false);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    async function fetchProfile() {
      const id =localStorage.getItem("userId") 
      setLoading(true);
      try {
        const data = await getProfile(id);
        setProfile({
          ...initialProfile,
          ...data,
          address: { ...initialProfile.address, ...data.address },
          availability: { ...initialProfile.availability, ...data.availability },
        });
        setAvatarUrl(data.avatarUrl);
      } catch (err) {
        // handle error
      }
      setLoading(false);
    }
    fetchProfile();
   
  }, []);



  const handleChange = (field, value) => {
    setProfile((prev) => ({ ...prev, [field]: value }));
  };

  const handleAddressChange = (field, value) => {
    setProfile((prev) => ({ ...prev, address: { ...prev.address, [field]: value } }));
  };

  const handleAvailabilityChange = (field, value) => {
    setProfile((prev) => ({ ...prev, availability: { ...prev.availability, [field]: value } }));
  };

  const handleQualificationsChange = (idx, value) => {
    setProfile((prev) => {
      const qualifications = [...prev.qualifications];
      qualifications[idx] = value;
      return { ...prev, qualifications };
    });
  };

  const addQualification = () => {
    setProfile((prev) => ({ ...prev, qualifications: [...prev.qualifications, ""] }));
  };

  const removeQualification = (idx) => {
    setProfile((prev) => {
      const qualifications = prev.qualifications.filter((_, i) => i !== idx);
      return { ...prev, qualifications };
    });
  };

  const handleDaysChange = (idx, value) => {
    setProfile((prev) => {
      const days = [...prev.availability.days];
      days[idx] = value;
      return { ...prev, availability: { ...prev.availability, days } };
    });
  };

  const addDay = () => {
    setProfile((prev) => ({ ...prev, availability: { ...prev.availability, days: [...prev.availability.days, ""] } }));
  };

  const removeDay = (idx) => {
    setProfile((prev) => {
      const days = prev.availability.days.filter((_, i) => i !== idx);
      return { ...prev, availability: { ...prev.availability, days } };
    });
  };
  const handleAvatarUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
  
    setUploading(true);
  
    const formData = new FormData();
    formData.append("avatar", file);
  
    // Log to verify content
    for (let [key, value] of formData.entries()) {
      console.log(`${key}:`, value); // should log: avatar: File {...}
    }
  console.log("uploadAvatar" ,file);
  
    try {
      const data = await uploadAvatar(formData,file.name);
      console.log("Upload success:", data);
      setAvatarUrl(data.avatarUrl);
      setProfile((prev) => ({ ...prev, avatarUrl: data.avatarUrl }));
    } catch (err) {
      console.error("Upload failed", err);
    }
  
    setUploading(false);
  };
  

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSaving(true);
    try {
      await updateProfile(profile);
      alert("Profile saved!");
    } catch (err) {
      alert("Failed to save profile");
    }
    setSaving(false);
  };

  if (loading) return <div className="text-center py-10">Loading...</div>;

  return (
    <div className="max-w-2xl mx-auto py-8">
      <h1 className="text-2xl font-bold mb-6">Doctor Profile</h1>
      <Card className="p-6 shadow rounded-xl space-y-6">
        <form onSubmit={handleSubmit} className="space-y-6">
          {/* Personal Details */}
          <div>
            <h2 className="text-lg font-semibold mb-4">Personal Details</h2>
            <div className="flex items-center gap-6 mb-4">
              <div className="relative">
              <Avatar className="w-20 h-20">
                    <AvatarImage
src={
  avatarUrl?.startsWith("http")
    ? avatarUrl
    : avatarUrl
    ? `http://localhost:5000${avatarUrl}`
    : "/default-avatar.png"
}                        alt={profile.fullName}
                        onError={(e) => {
                        e.currentTarget.src = "/default-avatar.png"; 
                        }}
                    />
                    <AvatarFallback>
                        {profile?.fullName?.[0] || "U"}
                    </AvatarFallback>
                    </Avatar>               
                    <label className="absolute bottom-0 right-0 bg-white rounded-full shadow p-1 cursor-pointer border border-gray-200">
                  <input
                    type="file"
                    accept="image/*"
                    className="hidden"
                    onChange={handleAvatarUpload}
                  />
                  <span className="text-xs">{uploading ? "Uploading..." : "Edit"}</span>
                </label>
              </div>
              <div className="flex-1 grid grid-cols-1 gap-4">
                <Input
                  label="Full Name"
                  value={profile.fullName}
                  onChange={(e) => handleChange("fullName", e.target.value)}
                  placeholder="Full Name"
                  required
                />
                <Input
                  label="Specialization"
                  value={profile.specialization}
                  onChange={(e) => handleChange("specialization", e.target.value)}
                  placeholder="Specialization"
                  required
                />
              </div>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <Input
                label="Email"
                value={profile.email}
                onChange={(e) => handleChange("email", e.target.value)}
                placeholder="Email"
                type="email"
                required
              />
              <Input
                label="Phone"
                value={profile.phone}
                onChange={(e) => handleChange("phone", e.target.value)}
                placeholder="Phone"
                required
              />
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mt-4">
              <Input
                label="Gender"
                value={profile.gender}
                onChange={(e) => handleChange("gender", e.target.value)}
                placeholder="Gender"
              />
              <Input
                label="Age"
                value={profile.age}
                onChange={(e) => handleChange("age", e.target.value)}
                placeholder="Age"
                type="number"
              />
              <Input
                label="Country"
                value={profile.address.country}
                onChange={(e) => handleAddressChange("country", e.target.value)}
                placeholder="Country"
              />
            </div>
          </div>
          <Separator />
          {/* Qualifications */}
          <div>
            <h2 className="text-lg font-semibold mb-2">Qualifications</h2>
            {profile.qualifications.map((q, idx) => (
              <div key={idx} className="flex gap-2 mb-2">
                <Input
                  value={q}
                  onChange={(e) => handleQualificationsChange(idx, e.target.value)}
                  placeholder="Qualification"
                />
                <Button type="button" variant="outline" onClick={() => removeQualification(idx)}>-</Button>
              </div>
            ))}
            <Button type="button" variant="secondary" onClick={addQualification}>+ Add Qualification</Button>
          </div>
          <Separator />
          {/* Availability */}
          <div>
            <h2 className="text-lg font-semibold mb-2">Availability</h2>
            <div className="mb-2">Days:</div>
            {profile.availability.days.map((day, idx) => (
              <div key={idx} className="flex gap-2 mb-2">
                <Input
                  value={day}
                  onChange={(e) => handleDaysChange(idx, e.target.value)}
                  placeholder="Day"
                />
                <Button type="button" variant="outline" onClick={() => removeDay(idx)}>-</Button>
              </div>
            ))}
            <Button type="button" variant="secondary" onClick={addDay}>+ Add Day</Button>
            <div className="mt-4">
              <Input
                label="Time Slots"
                value={profile.availability.timeSlots}
                onChange={(e) => handleAvailabilityChange("timeSlots", e.target.value)}
                placeholder="e.g. 10am-6pm"
              />
            </div>
          </div>
          <Separator />
          {/* Experience */}
          <div>
            <h2 className="text-lg font-semibold mb-2">Experience</h2>
            <Input
              label="Experience (years)"
              value={profile.experience}
              onChange={(e) => handleChange("experience", e.target.value)}
              placeholder="Experience in years"
              type="number"
            />
          </div>
          <Button type="submit" className="w-full rounded-lg mt-4" disabled={saving}>{saving ? "Saving..." : "Save Changes"}</Button>
        </form>
      </Card>
    </div>
  );
} 